insert into style_refs (id, kind, title, notes, traits, recipe_id, seeded) values
('seed-avoid-01', 'avoid', 'Garbled, invented lettering',
 'Image models draw text as near-letters: extra strokes, melted serifs, words that almost spell the venue. Any lettering inside generated imagery is the fastest tell.',
 '["Never let a generative model render text", "All type is set from real font files", "Gig info must be exact and copy-checked"]', null, true),
('seed-avoid-02', 'avoid', 'Cinematic HDR gloss',
 'Everything rim-lit, over-sharpened and glossy, teal-and-orange grading, a plastic sheen on every surface. Reads as a render, not a print.',
 '["No teal/orange grading", "No uniform glossy sheen or rim light on everything", "Prefer flat ink colours and real photo grain"]', null, true),
('seed-avoid-03', 'avoid', 'Smoke, neon and lens-flare soup',
 'Atmospheric haze, neon tubes, sparks and lens flares stacked to fake drama.',
 '["No lens flares, sparks or volumetric smoke", "No neon-glow effects", "Drama comes from scale and contrast, not effects"]', null, true),
('seed-avoid-04', 'avoid', 'Plastic people and impossible instruments',
 'Faces that are not the band, waxy skin, extra fingers, guitars with too many tuning pegs or strings that go nowhere.',
 '["Never generate people, hands or instruments", "Only real band photos, placed untouched", "No face retouching or regeneration"]', null, true),
('seed-avoid-05', 'avoid', 'Dead-centre symmetry by default',
 'Subject in the middle, title centred on top, info centred at the bottom. Balanced, static and anonymous.',
 '["Use asymmetric grids and tension", "Let one element dominate by scale", "Centred layouts only when type contrast carries them (e.g. letterpress)"]', null, true),
('seed-avoid-06', 'avoid', 'Effects on type',
 'Chrome, bevels, outer glow, drop shadows and gradient-filled headlines.',
 '["Flat type in solid ink colours", "No glow, bevel, chrome or gradient fills", "Hierarchy through size, weight and placement"]', null, true),
('seed-avoid-07', 'avoid', 'Edge-to-edge detail with no rest',
 'Uniform detail density across the whole canvas, nowhere for the eye to land, no hierarchy.',
 '["Leave deliberate negative space", "One focal point, then a clear reading order", "Limit to a few large shapes"]', null, true),
('seed-avoid-08', 'avoid', 'Default synthwave palette',
 'Purple-to-blue gradients, magenta highlights and dark navy backgrounds that every model reaches for.',
 '["Limit to 2-4 flat ink colours", "Pick palettes from real print processes", "No unmotivated gradients"]', null, true),
('seed-avoid-09', 'avoid', 'Genre clip-art clichés',
 'Flaming guitars, skulls with roses, spotlit microphones, floating vinyl records.',
 '["The band photo or logo is the image", "Shapes are abstract and graphic, not illustrative clichés"]', null, true),
('seed-avoid-10', 'avoid', 'Info as an afterthought',
 'Date, venue and time tucked in tiny type, hallucinated or unreadable from a distance.',
 '["Who, when and where must read from ten feet", "Date and venue get real size and contrast", "Check contrast of every text block"]', null, true),
('seed-avoid-11', 'avoid', 'Fake grunge overlays',
 'Uniform scratched-texture overlays and fake folds that do not follow any print logic.',
 '["Texture should imitate a real process: grain, halftone, paper, misregistration", "Keep texture subtle and consistent with the ink colours"]', null, true),

('seed-inspire-01', 'inspire', 'Swiss / International Typographic Style',
 'Josef Müller-Brockmann''s Zurich concert posters: a strict grid, flush-left sans serif, a single accent colour and black-and-white photography used as a graphic shape.',
 '["Asymmetric modular grid", "Flush-left grotesque type", "Black-and-white photo plus one accent colour", "Information set as a clean typographic table"]', 'swiss', true),
('seed-inspire-02', 'inspire', 'Hatch Show Print letterpress',
 'Nashville wood-type posters: stacked lines of type in contrasting sizes, horizontal rules, two inks (often red and black) on cream or kraft stock.',
 '["Stacked wood-type lines that each fill the measure", "Two ink colours on warm paper", "Rules and bands divide the information", "Centred layout carried by dramatic size contrast"]', 'letterpress', true),
('seed-inspire-03', 'inspire', 'Blue Note Records (Reid Miles)',
 'Tight, surprising photo crops tinted in one colour, bold type with big scale jumps and confident negative space.',
 '["Crop photos boldly", "Single-colour photo tint", "Huge scale contrast in type", "Generous negative space"]', 'bluenote', true),
('seed-inspire-04', 'inspire', 'Late-70s punk photocopy flyers',
 'Black Flag and Sex Pistols era handbills: photocopied high-contrast photos, cut-and-paste layout, tape, hand-set type.',
 '["Threshold (1-bit) photocopy photos", "Slightly rotated, pasted-on elements", "Typewriter and condensed display type", "Black ink on white or coloured paper"]', 'punk', true),
('seed-inspire-05', 'inspire', 'Modern screenprinted gig posters',
 'The 1990s-2010s rock poster scene: two or three spot colours, flat shapes, overprinting and slight misregistration.',
 '["Two or three spot colours", "Duotone photos", "Visible overprint and misregistration", "Bold flat geometric shapes"]', 'screenprint', true),
('seed-inspire-06', 'inspire', 'Risograph zine flyers',
 'Fluorescent pink and blue inks overprinted with multiply, grainy coverage and mono type.',
 '["Fluoro pink plus blue overprint", "Multiply blend where inks overlap", "Visible grain", "Grotesk headline with mono details"]', 'riso', true),
('seed-inspire-07', 'inspire', '1960s Fillmore & Avalon posters',
 'Wes Wilson and Victor Moscoso: vibrating complementary colours and radial compositions. Used with restraint: flat inks, no airbrushed glow.',
 '["Complementary colour vibration with flat inks", "Radial or sunburst structure", "Rounded display type", "Photo framed in a circle"]', 'psych', true),
('seed-inspire-08', 'inspire', 'Telephone-pole handbill',
 'The flyer that works across the street: one image, the band name huge, date and venue impossible to miss.',
 '["Readable from ten feet", "One image, one headline", "Date and venue at least a quarter the size of the band name"]', null, true)
on conflict (id) do nothing;
